package net.civeira.phylax.feature.oauth.userinvitation.infrastructure.driver.rest;

import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;

import jakarta.enterprise.context.RequestScoped;
import jakarta.ws.rs.Consumes;
import jakarta.ws.rs.DELETE;
import jakarta.ws.rs.FormParam;
import jakarta.ws.rs.GET;
import jakarta.ws.rs.POST;
import jakarta.ws.rs.Path;
import jakarta.ws.rs.PathParam;
import jakarta.ws.rs.Produces;
import jakarta.ws.rs.QueryParam;
import jakarta.ws.rs.core.MediaType;
import jakarta.ws.rs.core.Response;
import lombok.Data;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.civeira.phylax.common.infrastructure.CurrentRequest;
import net.civeira.phylax.common.security.Actor;
import net.civeira.phylax.feature.identity.tenant.domain.Tenant;
import net.civeira.phylax.feature.identity.tenant.domain.TenantReference;
import net.civeira.phylax.feature.identity.tenant.domain.gateway.TenantFilter;
import net.civeira.phylax.feature.identity.tenant.domain.gateway.TenantQueryRepositoryGateway;
import net.civeira.phylax.feature.identity.user.domain.gateway.UserFilter;
import net.civeira.phylax.feature.identity.user.domain.gateway.UserQueryRepositoryGateway;
import net.civeira.phylax.feature.oauth.client.domain.gateway.ClientStoreGateway;
import net.civeira.phylax.feature.oauth.theme.domain.gateway.DecoratePageGateway;
import net.civeira.phylax.feature.oauth.userinvitation.application.InvitationAdminPolicy;
import net.civeira.phylax.feature.oauth.userinvitation.application.usecase.accept.InvitationAcceptParams;
import net.civeira.phylax.feature.oauth.userinvitation.application.usecase.accept.InvitationAcceptUsecase;
import net.civeira.phylax.feature.oauth.userinvitation.application.usecase.cancel.InvitationCancelUsecase;
import net.civeira.phylax.feature.oauth.userinvitation.application.usecase.create.InvitationCreateParams;
import net.civeira.phylax.feature.oauth.userinvitation.application.usecase.create.InvitationCreateResult;
import net.civeira.phylax.feature.oauth.userinvitation.application.usecase.create.InvitationCreateUsecase;
import net.civeira.phylax.feature.oauth.userinvitation.application.usecase.resend.InvitationResendUsecase;

/**
 * Invitation endpoints (task 2.2).
 *
 * <ul>
 * <li>{@code POST api/{tenant}/invitations}, {@code DELETE api/{tenant}/invitations/{uid}} and
 * {@code POST api/{tenant}/invitations/{uid}/resend}: bearer of an administrator of the tenant
 * ({@link InvitationAdminPolicy}); an invitation of another tenant is not found.</li>
 * <li>{@code GET} and {@code POST oauth/openid/{tenant}/invitation/accept}: the link of the email.
 * The form sets the password; the account is created once, and every invalid, used, cancelled or
 * expired link gets the same answer. With a registered {@code client_id} and {@code redirect_uri}
 * the page links back to the application.</li>
 * </ul>
 */
@Slf4j
@Path("")
@RequestScoped
@RequiredArgsConstructor
public class InvitationController {

  private final InvitationCreateUsecase create;
  private final InvitationCancelUsecase cancel;
  private final InvitationResendUsecase resend;
  private final InvitationAcceptUsecase accept;
  private final TenantQueryRepositoryGateway tenants;
  private final UserQueryRepositoryGateway users;
  private final ClientStoreGateway clients;
  private final CurrentRequest current;
  private final DecoratePageGateway decorator;

  @Data
  public static class InvitationRequest {
    private String email;
    private String roles;
    private String clientId;
    private String redirectUri;
  }

  @POST
  @Path("api/{tenant}/invitations")
  @Consumes(MediaType.APPLICATION_JSON)
  @Produces(MediaType.APPLICATION_JSON)
  public Response createInvitation(@PathParam("tenant") String tenantName, InvitationRequest body) {
    Optional<Tenant> tenant = managedTenant(tenantName);
    if (tenant.isEmpty()) {
      return Response.status(403).build();
    }
    if (body == null) {
      return error(400, "invalid_request", "A body with the email is required");
    }
    Actor actor = current.getActor();
    // The inviter is recorded by uid: an administrator whose account is not found cannot invite.
    Optional<String> inviterUid = users.find(UserFilter.builder().name(actor.getName())
        .tenant(TenantReference.of(actor.getTenant())).build()).map(user -> user.getUid());
    if (inviterUid.isEmpty()) {
      return Response.status(403).build();
    }
    String inviter = inviterUid.get();
    try {
      InvitationCreateResult result =
          create.create(InvitationCreateParams.builder().tenantName(tenantName)
              .tenantId(tenant.get().getUid()).email(body.getEmail()).invitedByUserUid(inviter)
              .invitedByEmail(actor.getName()).baseUrl(current.getPublicHost())
              .roles(body.getRoles()).clientId(body.getClientId() == null ? "" : body.getClientId())
              .redirectUri(body.getRedirectUri() == null ? "" : body.getRedirectUri()).build());
      Map<String, Object> created = new LinkedHashMap<>();
      created.put("uid", result.uid());
      created.put("expires_at", result.expiresAt().toString());
      return Response.status(201).entity(created).build();
    } catch (IllegalArgumentException ex) {
      return error(400, "invalid_request", ex.getMessage());
    } catch (IllegalStateException ex) {
      return error(409, "conflict", ex.getMessage());
    }
  }

  @DELETE
  @Path("api/{tenant}/invitations/{uid}")
  public Response cancelInvitation(@PathParam("tenant") String tenantName,
      @PathParam("uid") String uid) {
    return managedTenant(tenantName)
        .map(tenant -> cancel.cancel(uid, tenant.getUid()) ? Response.noContent().build()
            : Response.status(404).build())
        .orElseGet(() -> Response.status(403).build());
  }

  @POST
  @Path("api/{tenant}/invitations/{uid}/resend")
  public Response resendInvitation(@PathParam("tenant") String tenantName,
      @PathParam("uid") String uid) {
    return managedTenant(tenantName)
        .map(tenant -> resend.resend(uid, tenantName, tenant.getUid(), current.getPublicHost())
            ? Response.noContent().build()
            : Response.status(404).build())
        .orElseGet(() -> Response.status(403).build());
  }

  @GET
  @Path("oauth/openid/{tenant}/invitation/accept")
  @Produces(MediaType.TEXT_HTML)
  public Response acceptForm(@PathParam("tenant") String tenantName,
      @QueryParam("token") String token, @QueryParam("client_id") String clientId,
      @QueryParam("redirect_uri") String redirectUri) {
    try {
      accept.open(tenantName, token);
    } catch (IllegalArgumentException ex) {
      return page(tenantName, 400, "<h1>Invitation</h1><p>" + escape(ex.getMessage()) + "</p>");
    }
    return page(tenantName, 200,
        "<h1>Accept the invitation</h1>"
            + "<form method=\"POST\"><input type=\"hidden\" name=\"token\" value=\"" + escape(token)
            + "\" /><input type=\"hidden\" name=\"client_id\" value=\"" + escape(orEmpty(clientId))
            + "\" /><input type=\"hidden\" name=\"redirect_uri\" value=\""
            + escape(orEmpty(redirectUri)) + "\" /><label>Password <input type=\"password\""
            + " name=\"password\" minlength=\"" + InvitationAcceptUsecase.MIN_PASSWORD
            + "\" required /></label><input class=\"primary-button\" type=\"submit\""
            + " value=\"Create account\" /></form>");
  }

  @POST
  @Path("oauth/openid/{tenant}/invitation/accept")
  @Consumes(MediaType.APPLICATION_FORM_URLENCODED)
  @Produces(MediaType.TEXT_HTML)
  public Response acceptInvitation(@PathParam("tenant") String tenantName,
      @FormParam("token") String token, @FormParam("password") String password,
      @FormParam("client_id") String clientId, @FormParam("redirect_uri") String redirectUri) {
    try {
      String email = accept.accept(
          InvitationAcceptParams.builder().rawToken(token).tenantName(tenantName).password(password)
              .clientId(orEmpty(clientId)).redirectUri(orEmpty(redirectUri)).build())
          .getEmail();
      String back = isRegistered(tenantName, clientId, redirectUri)
          ? "<p><a href=\"" + escape(redirectUri) + "\">Continue to the application</a></p>"
          : "";
      return page(tenantName, 200,
          "<h1>Account created</h1><p>You can now sign in as " + escape(email) + ".</p>" + back);
    } catch (IllegalArgumentException ex) {
      return page(tenantName, 400, "<h1>Invitation</h1><p>" + escape(ex.getMessage()) + "</p>");
    }
  }

  /**
   * The tenant of the route when the caller administers it.
   */
  private Optional<Tenant> managedTenant(String tenantName) {
    return tenants.find(TenantFilter.builder().name(tenantName).build()).filter(
        tenant -> InvitationAdminPolicy.allows(current.getActor(), tenant.getUid(), tenantName));
  }

  private boolean isRegistered(String tenant, String clientId, String redirectUri) {
    return clientId != null && !clientId.isBlank() && redirectUri != null && !redirectUri.isBlank()
        && clients.loadForAuthorization(tenant, clientId, redirectUri).isPresent();
  }

  private Response page(String tenant, int status, String body) {
    return Response.status(status)
        .entity(decorator.getFullPage(tenant, "Invitation", body, Locale.ENGLISH))
        .type(MediaType.TEXT_HTML).header("Cache-Control", "no-store")
        .header("Referrer-Policy", "no-referrer").build();
  }

  private static Response error(int status, String error, String description) {
    return Response.status(status).entity(Map.of("error", error, "error_description", description))
        .type(MediaType.APPLICATION_JSON).build();
  }

  private static String orEmpty(String value) {
    return value == null ? "" : value;
  }

  private static String escape(String value) {
    return value == null ? ""
        : value.replace("&", "&amp;").replace("\"", "&quot;").replace("'", "&#39;")
            .replace("<", "&lt;").replace(">", "&gt;");
  }
}
